:root {
  /* Colors */
  --color-ink-canvas: #041734;
  --color-jet-well: #001027;
  --color-carbon-panel: #0a1929;
  --color-frosted-glass: #ffffff0d;
  --color-ash-comment: #445458;
  --color-fog-caption: #a7babe;
  --color-paper: #ffffff;
  --color-steel-hairline: #6094c133;
  --color-cobalt-signal: #0075ff;
  --color-moss-pulse: #2ea45d;
  --color-mint-pulse: #4ade80;
  --color-ember-alert: #ef4444;
  --color-sunshine-warn: #eab308;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-apple-system: -apple-system, ui-sans-serif, system-ui, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 9px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.625;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-subheading: 16px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.4;
  --tracking-heading-sm: 0px;
  --text-heading: 36px;
  --leading-heading: 1.11;
  --tracking-heading: -1.44px;
  --text-display: 48px;
  --leading-display: 1;
  --tracking-display: -1.92px;
  --tracking-eyebrow: -0.35px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-112: 112px;

  /* Layout */
  --layout-max-width: 1536px;
  --layout-section-gap: 96px;
  --layout-card-padding: 16px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 12px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-tags: 4px;
  --radius-inner-tiles: 6px;
  --radius-buttons: 8px;
  --radius-inputs: 8px;
  --radius-nav: 8px;
  --radius-cards: 12px;
  --radius-pills: 9999px;
  --radius-badges: 9999px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: 0px 0px 0px 4px rgba(59, 130, 246, 0.18);
  --shadow-sm: 0px 2px 12px 0px rgba(0, 0, 0, 0.5);
  --shadow-md: 0px 4px 12px 0px rgba(0, 0, 0, 0.25), 0px 1px 3px 0px rgba(0, 0, 0, 0.15), inset 0px 1px 0px 0px rgba(255, 255, 255, 0.04);
  --shadow-md-2: 0px 0px 20px -6px rgba(239, 68, 68, 0.35), inset 0px 0px 24px -8px rgba(239, 68, 68, 0.08);
  --shadow-lg: 0px 2px 4px 0px rgba(0, 0, 0, 0.1), 0px 8px 24px 0px rgba(0, 0, 0, 0.18), 0px 32px 72px 0px rgba(0, 0, 0, 0.32);
  --shadow-xl: 0px 2px 20px 0px rgba(0, 0, 0, 0.55), 0px 0px 40px -16px rgba(59, 130, 246, 0.15);

  /* Surfaces */
  --surface-ink-canvas: #041734;
  --surface-carbon-panel: #0a1929;
  --surface-jet-well: #001027;
  --surface-frosted-glass: #ffffff0d;
  --surface-paper: #ffffff;
}

